  # Resolve the outbound URL for a connection: the author-provided profile URL,
  # else the platform's base URL joined to the (de-@'d) handle.
  def social_url(user_social)
    return user_social.profile_url if user_social.profile_url.present?

    base = user_social.social_platform&.base_url.to_s
    handle = user_social.handle.to_s.strip.delete_prefix("@")
    base.present? ? "#{base}#{handle}" : nil
  end

  # Inline brand SVG for a connection, falling back to a neutral link glyph.
  def social_icon(user_social, **opts)
    classes = opts[:class] || "w-5 h-5"
    slug    = user_social.social_platform&.slug.to_s
    inner   = SOCIAL_ICONS[slug] || %(<path fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" d="M13.828 10.172a4 4 0 010 5.656l-3 3a4 4 0 11-5.656-5.656l1.5-1.5m6.328-2.828a4 4 0 010-5.656l3-3a4 4 0 115.656 5.656l-1.5 1.5"/>)
    tag.svg(raw(inner), class: classes, viewBox: "0 0 24 24",
            fill: (SOCIAL_ICONS.key?(slug) ? "currentColor" : "none"),
            "aria-hidden": "true")
  end
end
